    "\n    *[_type == \"workflowTemplate\" && slug.current == $slug][0] {\n      _id,\n      title,\n      slug,\n      excerpt,\n      content,\n      publishedAt,\n      \"updatedAt\": _updatedAt,\n      featuredImage,\n      \"workflowJsonUrl\": workflowJson.asset->url,\n      n8nUrl,\n      youtubeUrl,\n      loomUrl,\n      railwayTemplates[]{\n        label,\n        deployUrl\n      },\n      categories[]-> {\n        _id,\n        name,\n        slug\n      },\n      author-> {\n        name,\n        image,\n        bio\n      },\n      relatedBlogPosts[]-> {\n        _id,\n        title,\n        slug,\n        excerpt,\n        featuredImage,\n        publishedAt,\n        content,\n        categories[]-> { _id, name, slug }\n      },\n      seo {\n        metaTitle,\n        metaDescription\n      }\n    }\n  ": WORKFLOW_TEMPLATE_QUERYResult;
